static std::vector<ImVec4> gCrtHoles;	// screen rects the CRT effect leaves alone this frame (texture / model previews)
// rectangle subtraction: `rects` minus `hole`, pieces appended to `out`
static void rectsMinus(const std::vector<ImVec4> &rects, const ImVec4 &h, std::vector<ImVec4> &out)
{
	for(size_t i = 0; i < rects.size(); i++){
		const ImVec4 &r = rects[i];
		if(h.x >= r.z || h.z <= r.x || h.y >= r.w || h.w <= r.y){ out.push_back(r); continue; }
		float hx0 = h.x > r.x ? h.x : r.x, hx1 = h.z < r.z ? h.z : r.z, hy0 = h.y > r.y ? h.y : r.y, hy1 = h.w < r.w ? h.w : r.w;
		if(hy0 > r.y) out.push_back(ImVec4(r.x, r.y, r.z, hy0));		// above
		if(hy1 < r.w) out.push_back(ImVec4(r.x, hy1, r.z, r.w));		// below
		if(hx0 > r.x) out.push_back(ImVec4(r.x, hy0, hx0, hy1));		// left
		if(hx1 < r.z) out.push_back(ImVec4(hx1, hy0, r.z, hy1));		// right
	}
}
static std::vector<ImVec4> screenMinusHoles(float W, float H)
{
	std::vector<ImVec4> cur; cur.push_back(ImVec4(0, 0, W, H));
	for(size_t i = 0; i < gCrtHoles.size(); i++){ std::vector<ImVec4> next; rectsMinus(cur, gCrtHoles[i], next); cur.swap(next); }
	return cur;
}

// What the table shows: three or more rows with the same code in the same archive / file collapse into
// one header row («+ CUT-07 · cuts.img · ×695»), a click unfolds them. Keys of unfolded groups persist.
struct DispRow { int issue; int count; int sev; bool header; std::string key; };
static std::vector<DispRow> gDisplay;
static std::set<std::string> gExpanded;
static std::string groupContainer(const Issue &is)
{
	size_t sl = is.file.find('/');	// "archive.img/entry" → the archive; any other file → the file itself (the line is a separate field)
	if(sl != std::string::npos){ std::string a = lower(is.file.substr(0, sl)); if(a.size() > 4 && a.compare(a.size() - 4, 4, ".img") == 0) return is.file.substr(0, sl); }
	return is.file;
}
static void buildDisplay()
{
	gDisplay.clear();
	std::unordered_map<std::string, int> counts;
	std::vector<std::string> keys(gFiltered.size());
	for(size_t i = 0; i < gFiltered.size(); i++){ const Issue &is = gSnapshot[(size_t)gFiltered[i]]; keys[i] = is.code + "|" + lower(groupContainer(is)); counts[keys[i]]++; }
	std::set<std::string> emitted;
	for(size_t i = 0; i < gFiltered.size(); i++){
		const std::string &k = keys[i];
		int idx = gFiltered[i];
		if(counts[k] < 3){ gDisplay.push_back({ idx, 1, gSnapshot[(size_t)idx].sev, false, k }); continue; }
		if(!emitted.insert(k).second) continue;
		int worst = 0;
		for(size_t j = i; j < gFiltered.size(); j++) if(keys[j] == k && gSnapshot[(size_t)gFiltered[j]].sev > worst) worst = gSnapshot[(size_t)gFiltered[j]].sev;
		gDisplay.push_back({ idx, counts[k], worst, true, k });
		if(gExpanded.count(k)) for(size_t j = i; j < gFiltered.size(); j++) if(keys[j] == k) gDisplay.push_back({ gFiltered[j], 1, gSnapshot[(size_t)gFiltered[j]].sev, false, k + "#" });
	}
}
