// Amber phosphor terminal: everything in one warm colour on black — bright amber text, dim amber for
// secondary text, 1 px amber outlines with a small radius, black plates. Severity keeps four warm steps
// (crash red-orange, error amber, warning pale, info dim) so the levels still read at a glance.
static Skin gTermSkin;	// filled by termSkinFor() from the phosphor colour picked in the settings
// Phosphor presets (Настройки → «цвет» in the terminal theme, ini `termhue=`): accent, text, and four
// severity colours chosen to stay apart from the text colour of that preset.
enum { HUE_AMBER = 0, HUE_GREEN, HUE_RED, HUE_CYAN, HUE_WHITE, HUE_NUM };
static int gTermHue = HUE_AMBER;
static void termSkinFor(int hue)
{
	struct P { ImVec4 accent, text, sev[4]; };
	static const P presets[HUE_NUM] = {
		{ ImVec4(0.94f, 0.63f, 0.16f, 1), ImVec4(0.96f, 0.70f, 0.28f, 1), { ImVec4(0.55f, 0.68f, 0.80f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.46f, 0.08f, 1), ImVec4(0.96f, 0.24f, 0.22f, 1) } },
		{ ImVec4(0.30f, 0.92f, 0.42f, 1), ImVec4(0.55f, 1.00f, 0.60f, 1), { ImVec4(0.55f, 0.68f, 0.85f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.55f, 0.15f, 1), ImVec4(0.98f, 0.25f, 0.22f, 1) } },
		{ ImVec4(0.96f, 0.28f, 0.24f, 1), ImVec4(1.00f, 0.46f, 0.40f, 1), { ImVec4(0.60f, 0.70f, 0.85f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.68f, 0.25f, 1), ImVec4(1.00f, 0.95f, 0.90f, 1) } },
		{ ImVec4(0.25f, 0.85f, 0.90f, 1), ImVec4(0.55f, 0.95f, 1.00f, 1), { ImVec4(0.50f, 0.58f, 0.66f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.55f, 0.15f, 1), ImVec4(0.98f, 0.25f, 0.22f, 1) } },
		{ ImVec4(0.84f, 0.84f, 0.84f, 1), ImVec4(0.95f, 0.95f, 0.95f, 1), { ImVec4(0.55f, 0.68f, 0.85f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.55f, 0.15f, 1), ImVec4(0.98f, 0.25f, 0.22f, 1) } },
	};
	if(hue < 0 || hue >= HUE_NUM) hue = HUE_AMBER;
	const P &q = presets[hue];
	ImVec4 a = q.accent;
	Skin &t = gTermSkin;
	t.accent = a;
	t.accentHi = ImVec4(a.x * 0.85f + 0.15f, a.y * 0.85f + 0.15f, a.z * 0.85f + 0.15f, 1);
	t.accentLo = ImVec4(a.x * 0.70f, a.y * 0.70f, a.z * 0.70f, 1);
	t.text = q.text;
	t.dim = ImVec4(a.x * 0.64f, a.y * 0.64f, a.z * 0.64f, 1);
	t.childBg = ImVec4(a.x * 0.022f, a.y * 0.022f, a.z * 0.022f, 1);
	t.frameBg = ImVec4(a.x * 0.048f, a.y * 0.048f, a.z * 0.048f, 1);
	t.headerBg = ImVec4(a.x * 0.075f, a.y * 0.075f, a.z * 0.075f, 1);
	t.border = ImVec4(a.x, a.y, a.z, 0.80f);
	for(int i = 0; i < 4; i++) t.sev[i] = q.sev[i];
	t.overlay = IM_COL32(0, 0, 0, 255);
	for(int i = 0; i < 4; i++) t.grad[i] = IM_COL32(0, 0, 0, 255);
}
static const Skin *gSkin = &SKIN_SA;		// effective palette (game skin, gBlenderSkin or gTermSkin)
static const Skin *gGameSkin = &SKIN_SA;	// palette picked by the checked game
// Three looks: THEME_PAUSE = the loading-screen art behind dense dark plates, Russo One for the HUD-like
// bits; THEME_CALM = flat neutral greys, no art, Inter everywhere, the game's accent as the single colour
// (Linear-style); THEME_BLENDER = Blender's own widgets, greys, blue and Inter, game palette ignored.
// THEME_TERM = an amber CRT terminal: monospace JetBrains Mono, one colour on black, outlined boxes,
// optional scanlines (ini `crt=`). Picked in «Настройки…», ini `theme=`.
// THEME_PANEL = a dashboard: navigation in a left sidebar, the levels as big cards, the table and the
// details in rounded cards on a navy ground, blue accent; the flat (calm) widgets and Inter underneath.
// THEME_STUDIO = the search in the header, the preview under the table, a properties / dependencies panel
// with the actions on the right, the counters in the status line; same navy palette as the panel theme.
enum { THEME_PAUSE = 0, THEME_CALM = 1, THEME_BLENDER = 2, THEME_TERM = 3, THEME_PANEL = 4, THEME_STUDIO = 5, THEME_NUM };
static int gTheme = THEME_STUDIO;	// the layout is always the studio; the old themes survive as colour schemes (gScheme)
// Colour schemes (Настройки → «цвета», ini scheme=): the palettes of the former themes on the one studio layout.
// «неон» keeps the whole terminal look: JetBrains Mono, phosphor colour, outlines, CRT scanlines / glow / curved 3D.
enum { SCH_STUDIO = 0, SCH_GAME, SCH_CALM, SCH_BLENDER, SCH_NAVY, SCH_NEON, SCH_GRAPHITE, SCH_INDIGO, SCH_OCEAN, SCH_NUM };
static int gScheme = SCH_STUDIO;
static ImU32 gGroundCol = IM_COL32(17, 17, 17, 255);	// the ground behind everything, from the scheme (applySkin)
static ImVec4 gGroundVec(0.067f, 0.067f, 0.067f, 1);
static bool gThemeDirty;	// re-apply the style at the next frame start (never mid-frame: pushes would restore old colours)
static bool gCrtLines = true;	// terminal theme: scanline overlay
static float gUiScale = 1.0f;	// 1 / 1.25 / 1.5 — fonts are baked at size × scale, the style sizes scaled (ini `scale=`)
static bool gScaleDirty = false;	// rebake the atlas at the next frame start
static bool gRefitColumns = false;	// table columns re-measured with the new fonts
// the layout predicates: only the studio remains; «neon» is the terminal scheme (mono fonts, glow, CRT)
static inline bool panelTheme() { return false; }
static inline bool studioTheme() { return true; }
static inline bool navyTheme() { return true; }
static inline bool calm() { return true; }
static inline bool blender() { return false; }
static inline bool term() { return gScheme == SCH_NEON; }
static inline bool artTheme() { return false; }
