// "COL-23a" comes from the table, the reference has "COL-23"
static bool refCodeMatches(const std::string &row, const std::string &want)
{
	if(want.empty()) return false;
	if(row == want) return true;
	return want.size() > 1 && isalpha((unsigned char)want.back()) && row == want.substr(0, want.size() - 1);
}

static void drawRuleRef()
{
	if(!gRefOpen) return;
	ImGuiIO &io = ImGui::GetIO();
	ImGui::SetNextWindowSize(ImVec2(io.DisplaySize.x * 0.7f, io.DisplaySize.y * 0.75f), ImGuiCond_FirstUseEver);
	ImGui::SetNextWindowPos(ImVec2(io.DisplaySize.x * 0.5f, io.DisplaySize.y * 0.5f), ImGuiCond_FirstUseEver, ImVec2(0.5f, 0.5f));
	if(!ImGui::Begin(T("Справочник"), &gRefOpen, ImGuiWindowFlags_NoCollapse)){ ImGui::End(); return; }
	// the sections as tabs along the top, like pages in a browser (the user's request); the content follows the bar
	int tab = -1;
	if(ImGui::BeginTabBar("reftabs", ImGuiTabBarFlags_None)){
		ImGui::PushFont(headFont(), headSize());
		if(ImGui::BeginTabItem(T("Коды правил"), nullptr, gRefTabReq == 0 ? ImGuiTabItemFlags_SetSelected : 0)){ tab = 0; ImGui::EndTabItem(); }
		if(ImGui::BeginTabItem(T("Клавиши и мышь"), nullptr, gRefTabReq == 1 ? ImGuiTabItemFlags_SetSelected : 0)){ tab = 1; ImGui::EndTabItem(); }
		ImGui::PopFont();
		ImGui::EndTabBar();
	}
	gRefTabReq = -1;
	if(tab == 1){ drawKeysRef(); ImGui::End(); return; }
	ImGui::SetNextItemWidth(320.0f);
	int pushed = pushFieldFrame(false);
	ImGui::InputTextWithHint("##refsearch", T("Поиск по коду и тексту"), gRefSearch, sizeof(gRefSearch));
	ImGui::PopStyleColor(pushed);
	ImGui::SameLine();
	ImGui::TextDisabled(T("%d правил"), RuleHelpCount());
	std::string q = lower(trim(gRefSearch));
	int pushed2 = 0;
	if(blender()){ ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.157f, 0.157f, 0.157f, 1)); pushed2 = 1; }
	if(ImGui::BeginTable("ref", 4, ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable, ImVec2(0, 0))){
		ImGui::TableSetupScrollFreeze(0, 1);
		ImGui::TableSetupColumn(T("Код"), ImGuiTableColumnFlags_WidthFixed, 90.0f);
		ImGui::TableSetupColumn(T("Что это"), ImGuiTableColumnFlags_WidthStretch, 1.0f);
		ImGui::TableSetupColumn(T("Чем грозит"), ImGuiTableColumnFlags_WidthStretch, 1.0f);
		ImGui::TableSetupColumn(T("Что делать"), ImGuiTableColumnFlags_WidthStretch, 1.0f);
		ImGui::PushFont(headFont(), headSize());
		ImGui::TableHeadersRow();
		ImGui::PopFont();
		ImGui::PushFont(readFont(), readSize());
		for(int i = 0; i < RuleHelpCount(); i++){
			std::string code, what, risk, fix;
			if(!RuleHelpAt(i, code, what, risk, fix)) continue;
			if(code.find('-') == std::string::npos) continue;	// family fallbacks
			if(!q.empty() && lower(code).find(q) == std::string::npos && lower(what).find(q) == std::string::npos && lower(risk).find(q) == std::string::npos && lower(fix).find(q) == std::string::npos) continue;
			ImGui::TableNextRow();
			ImGui::TableSetColumnIndex(0);
			bool marked = refCodeMatches(code, gRefMark);
			if(marked) ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg0, col32(SA_ORANGE, 0.22f));	// the row the user came from
			if(!gRefJump.empty() && refCodeMatches(code, gRefJump)){ ImGui::SetScrollHereY(0.2f); gRefJump.clear(); }
			if(marked){
				ImVec2 a = ImGui::GetCursorScreenPos();
				ImGui::GetWindowDrawList()->AddRectFilled(ImVec2(a.x - 4.0f, a.y - 2.0f), ImVec2(a.x - 1.0f, a.y + ImGui::GetTextLineHeight() + 2.0f), col32(SA_ORANGE, 1.0f));
			}
			ImGui::TextColored(SA_ORANGE_HI, "%s", code.c_str());
			ImGui::TableSetColumnIndex(1); ImGui::PushTextWrapPos(0); ImGui::TextUnformatted(what.c_str()); ImGui::PopTextWrapPos();
			ImGui::TableSetColumnIndex(2); ImGui::PushTextWrapPos(0); ImGui::TextUnformatted(risk.c_str()); ImGui::PopTextWrapPos();
			ImGui::TableSetColumnIndex(3); ImGui::PushTextWrapPos(0); ImGui::TextUnformatted(fix.c_str()); ImGui::PopTextWrapPos();
		}
		ImGui::PopFont();
		ImGui::EndTable();
	}
	ImGui::PopStyleColor(pushed2);
	ImGui::End();
}

